import { watch } from "./watch";

export function retry(input, limit) {
  let attempt = 0;
  for (;;) {
    try {
      return send(input);
    } catch (e) {
      attempt += 1;
      if (attempt < limit) continue;
      throw e;
    }
  }
}

export const saveIssue = operation({
  label: "saveIssue",
  input: parseEditInput,
  depends: { tx: store.tx },
  run: async ({ tx }, { input }) => {
    const rows = await tx.select().from(issueRows);
    return rows[0];
  },
});

export function total(xs) {
  let sum = 0;
  for (const x of xs) sum += x;
  return sum;
}
